const{redis:redis,requireAdmin:requireAdmin}=require("./_lib/auth");module.exports=async function(e,t){if(t.setHeader("Cache-Control","no-store"),"GET"!==e.method)return t.setHeader("Allow",["GET"]),void t.status(405).json({error:"Method not allowed"});if(requireAdmin(e,t))try{const e=(await redis.keys("household:*:__meta")).map(e=>{const t=e.match(/^household:(.+):__meta$/);return t?t[1]:null}).filter(Boolean),o=await Promise.all(e.map(async e=>{let t={};try{const o=await redis.get(`household:${e}:__meta`);t=o?JSON.parse(o):{}}catch{t={}}return{code:e,updatedAt:t.updatedAt||null,lastChangedKey:t.changedKey||null}}));o.sort((e,t)=>(t.updatedAt||0)-(e.updatedAt||0)),t.status(200).json({households:o,count:o.length})}catch(e){console.error("admin households list error",e),t.status(500).json({error:"Failed to list households"})}};